import { Scene } from "retiam";
import { Axes, Dot, AnnotationDot, GlowDot, LabeledDot, Color, GrowFromCenter, FadeIn } from "retiam";

export class DotShowcaseScene extends Scene {
    public async construct() {
        // 1. Setup coordinate grid
        const axes = new Axes({
            xRange: [-6, 6, 1],
            yRange: [-4, 4, 1],
            xLength: 12,
            yLength: 8
        });
        await this.play(axes.animate.fadeIn());

        // 2. Add AnnotationDot at curve peak
        const peak = new AnnotationDot(axes.c2p(0, 2), 0.12, {
            fillColor: Color.fromHex("#FF4444"),
            strokeColor: Color.WHITE
        });
        await this.play(new GrowFromCenter(peak));

        // 3. Add LabeledDots at triangle vertices
        const dotA = axes.getLabeledDot("A", [-4, 2], { radius: 0.28, fill: Color.BLUE });
        const dotB = axes.getLabeledDot("B", [4, 2], { radius: 0.28, fill: Color.GREEN });
        const dotC = axes.getLabeledDot("C", [0, -2], { radius: 0.28, fill: Color.ORANGE });
        await this.play(new FadeIn(dotA), new FadeIn(dotB), new FadeIn(dotC));

        // 4. Add Stepped Halo Beacon at origin
        const beacon = new GlowDot(axes.c2p(0, 0), 0.12, {
            glowColor: Color.CYAN,
            glowRadius: 0.55,
            glowType: 'stepped',
            glowSteps: 5
        });
        this.add(beacon);

        // 5. Add Continuous Smooth Orbiting Glow Tracer
        const tracer = new GlowDot(axes.c2p(-5, 0), 0.1, {
            glowColor: Color.YELLOW,
            glowRadius: 0.5,
            glowType: 'continuous',
            glowFalloff: 'exponential'
        });
        this.add(tracer);

        // Update tracer along sine curve
        let t = -5;
        this.always((time: number, dt: number) => {
            t += dt * 0.002;
            if (t > 5) t = -5;
            tracer.point = axes.c2p(t, 2 * Math.sin(0.8 * t));
        });

        await this.wait(3000);
    }
}
